SELECT INDEX_NAME, SEQ_IN_INDEX, COLUMN_NAME, NON_UNIQUE FROM INFORMATION_SCHEMA.STATISTICS
WHERE TABLE_SCHEMA='crypto_ai' AND TABLE_NAME='candle' ORDER BY INDEX_NAME, SEQ_IN_INDEX LIMIT 50;
SELECT TABLE_ROWS FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA='crypto_ai' AND TABLE_NAME IN ('candle','wallet_trade','wallet_cash_flow');